WITH dkey AS (SELECT id AS k, id AS doc_id FROM document UNION SELECT number AS k, id AS doc_id FROM document WHERE number IS NOT NULL), docn AS (SELECT id AS doc_id, COALESCE(number, id) AS doc_number, (CASE WHEN instr(replace(replace(replace(replace(replace(replace(upper(trim(target_release)),'RELEASE',''),'REL',''),'-',''),'_',''),' ',''),'R',''),'.') > 0 THEN substr(replace(replace(replace(replace(replace(replace(upper(trim(target_release)),'RELEASE',''),'REL',''),'-',''),'_',''),' ',''),'R',''),1,instr(replace(replace(replace(replace(replace(replace(upper(trim(target_release)),'RELEASE',''),'REL',''),'-',''),'_',''),' ',''),'R',''),'.')-1) ELSE replace(replace(replace(replace(replace(replace(upper(trim(target_release)),'RELEASE',''),'REL',''),'-',''),'_',''),' ',''),'R','') END) AS doc_rel FROM document), mods AS (SELECT cr, section_id FROM cr_modifies_section UNION SELECT cr, section_id FROM section_modified_by), crmod AS (SELECT DISTINCT dk.doc_id AS doc_id, dn.doc_number AS doc_number, dn.doc_rel AS doc_rel, s.spec AS spec, s.clause AS clause, (CASE WHEN instr(replace(replace(replace(replace(replace(replace(upper(trim(s.release)),'RELEASE',''),'REL',''),'-',''),'_',''),' ',''),'R',''),'.') > 0 THEN substr(replace(replace(replace(replace(replace(replace(upper(trim(s.release)),'RELEASE',''),'REL',''),'-',''),'_',''),' ',''),'R',''),1,instr(replace(replace(replace(replace(replace(replace(upper(trim(s.release)),'RELEASE',''),'REL',''),'-',''),'_',''),' ',''),'R',''),'.')-1) ELSE replace(replace(replace(replace(replace(replace(upper(trim(s.release)),'RELEASE',''),'REL',''),'-',''),'_',''),' ',''),'R','') END) AS sec_rel FROM mods m JOIN dkey dk ON dk.k = m.cr JOIN docn dn ON dn.doc_id = dk.doc_id JOIN section s ON s.id = m.section_id), mems AS (SELECT cr, pack_id FROM cr_in_pack UNION SELECT cr, pack_id FROM pack_member), pkey AS (SELECT id AS k, id AS pid FROM cr_pack UNION SELECT pack_number AS k, id AS pid FROM cr_pack WHERE pack_number IS NOT NULL), crpack AS (SELECT DISTINCT dk.doc_id AS doc_id, p.id AS pack_id, p.pack_number AS pack_number, p.tsg_meeting AS tsg_meeting, p.tsg_number AS tsg_number FROM mems y JOIN dkey dk ON dk.k = y.cr JOIN pkey pky ON pky.k = y.pack_id JOIN cr_pack p ON p.id = pky.pid), vdisp AS (SELECT DISTINCT dk.doc_id AS doc_id, x.code AS code, mt.label AS label FROM disposition x JOIN dkey dk ON dk.k = x.target JOIN resolution r ON r.id = x.resolution_id JOIN meeting mt ON mt.id = r.meeting_id WHERE replace(replace(replace(lower(trim(x.evidence_status)),'-',''),'_',''),' ','') IN ('sourceverified','verified','verifiedsource','verifiedfromsource','verifiedagainstsource') AND replace(replace(replace(lower(trim(x.scope)),'-',''),'_',''),' ','') IN ('wholedocument','document','whole','entiredocument','entire','fulldocument','full','all','alldocument','doc','wholedoc','fulldoc','tdoc','wholetdoc') AND (replace(replace(replace(lower(trim(mt.wg)),'-',''),'_',''),' ','') IN ('ran2','r2','ranwg2','wg2','tsgranwg2','tsgr2') OR replace(replace(replace(lower(trim(mt.wg)),'-',''),'_',''),' ','') LIKE '%ran2%' OR replace(replace(replace(lower(trim(mt.wg)),'-',''),'_',''),' ','') LIKE '%ranwg2%')), xdoc AS (SELECT doc_id FROM dkey WHERE k = '{ANCHOR}'), xcl AS (SELECT DISTINCT cm.spec AS spec, cm.clause AS clause, cm.sec_rel AS sec_rel FROM crmod cm WHERE cm.doc_id IN (SELECT doc_id FROM xdoc) AND cm.sec_rel = '18') SELECT DISTINCT c.clause AS clause, o.doc_number AS document, v.code AS disposition, v.label AS wg_meeting, cp.pack_number AS cr_pack FROM xcl c JOIN crmod o ON o.spec = c.spec AND o.clause = c.clause AND o.sec_rel = c.sec_rel JOIN vdisp v ON v.doc_id = o.doc_id JOIN crpack cp ON cp.doc_id = o.doc_id WHERE o.doc_id NOT IN (SELECT doc_id FROM xdoc) AND o.doc_rel = '18'
